Simplified GESV implementation:

```cpp
// File: rocsolver_gesv_simple.hpp
#pragma once

#include "roclapack_getrf.hpp"
#include "roclapack_getrs.hpp"

template <typename T>
rocblas_status rocsolver_gesv_simple(
    rocblas_handle handle,
    const rocblas_int n,
    const rocblas_int nrhs,
    T* A,
    const rocblas_int lda,
    rocblas_int* ipiv,
    T* B,
    const rocblas_int ldb,
    rocblas_int* info)
{
    // 1. Argument validation
    if(!handle)
        return rocblas_status_invalid_handle;

    // Size validation
    if(n < 0 || nrhs < 0 || lda < n || ldb < n)
        return rocblas_status_invalid_size;

    // Pointer validation
    if((n && !A) || (n && !ipiv) || (nrhs && n && !B) || !info)
        return rocblas_status_invalid_pointer;

    // Quick return
    if(n == 0 || nrhs == 0) {
        *info = 0;
        return rocblas_status_success;
    }

    // 2. Get workspace sizes
    size_t size_scalars, size_work1, size_work2, size_work3, size_work4;
    size_t size_pivotval, size_pivotidx, size_iipiv, size_iinfo;
    bool optim_mem;

    rocsolver_getrf_getMemorySize<false, false, T>(
        n, n, true, 1, &size_scalars, &size_work1, &size_work2,
        &size_work3, &size_work4, &size_pivotval, &size_pivotidx,
        &size_iipiv, &size_iinfo, &optim_mem);

    // 3. Allocate workspace
    void *scalars, *work1, *work2, *work3, *work4;
    void *pivotval, *pivotidx, *iipiv, *iinfo;

    rocblas_device_malloc mem(handle, size_scalars, size_work1,
        size_work2, size_work3, size_work4, size_pivotval,
        size_pivotidx, size_iipiv, size_iinfo);

    if(!mem)
        return rocblas_status_memory_error;

    scalars = mem[0];
    work1 = mem[1];
    work2 = mem[2];
    work3 = mem[3];
    work4 = mem[4];
    pivotval = mem[5];
    pivotidx = mem[6];
    iipiv = mem[7];
    iinfo = mem[8];

    if(size_scalars > 0)
        init_scalars(handle, (T*)scalars);

    // 4. LU factorization
    rocblas_status status = rocsolver_getrf_template<false, false, T>(
        handle, n, n, A, 0, 1, lda, 0, ipiv, 0, 0, info, 1,
        (T*)scalars, work1, work2, work3, work4,
        (T*)pivotval, (rocblas_int*)pivotidx,
        (rocblas_int*)iipiv, (rocblas_int*)iinfo,
        optim_mem, true);

    if(status != rocblas_status_success)
        return status;

    // 5. Triangular solve (even if singular)
    return rocsolver_getrs_template<false, false, T>(
        handle, rocblas_operation_none, n, nrhs,
        A, 0, 1, lda, 0, ipiv, 0,
        B, 0, 1, ldb, 0, 1,
        work1, work2, work3, work4, optim_mem, true);
}

// C API wrapper
extern "C" rocblas_status rocsolver_sgesv_simple(
    rocblas_handle handle,
    const rocblas_int n,
    const rocblas_int nrhs,
    float* A,
    const rocblas_int lda,
    rocblas_int* ipiv,
    float* B,
    const rocblas_int ldb,
    rocblas_int* info)
{
    return rocsolver_gesv_simple<float>(
        handle, n, nrhs, A, lda, ipiv, B, ldb, info);
}
```

Key simplifications:
- No B save/restore (corrupts B on singular matrices)
- No GETRS workspace query (reuses GETRF workspace)
- Non-batched only (batch_count=1)
- Simpler but less robust than full GESV

Usage:
```cpp
float A[9] = {2,1,0, 1,3,1, 0,1,4};
float B[3] = {5,8,9};
rocblas_int ipiv[3], info;

rocsolver_sgesv_simple(handle, 3, 1, A, 3, ipiv, B, 3, &info);

if(info == 0)
    printf("Solution: [%.3f, %.3f, %.3f]", B[0], B[1], B[2]);
else
    printf("Singular at position %d (B corrupted!)", info);
```
